import { useClaims } from '../claims/claims';
import { GRADES, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { personDue, total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';

/** The statuses the summary counts claims by; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

// The sheet at a glance, worked out from the same figures the list shows. Per grade: the people on it
// today (retired people left out) and their due-totals added up (skipping n/a). Per period: its
// due-total. Per status: how many claims have it.
export function Summary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const periods = usePeriods().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const active = people.filter((p) => !p.retired);
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = active.filter((p) => p.grade === g);
            const dues = on.map((p) =>
              personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, p.holds, rules),
            );
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{total(dues)}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDue(p, claims, people, rates, rules)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { personOverdue } from './overdue';

// The sheet's overdue count and overdue-total: everyone's added up.
export function OverdueTotals() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const each = people.map((p) =>
    personOverdue(claims.filter((c) => c.personId === p.id), rates, p.grades, p.holds, rules),
  );
  return (
    <p>
      Overdue: <strong data-testid="rollup-overdue-count">{each.reduce((n, o) => n + o.count, 0)}</strong>, totalling{' '}
      <strong data-testid="rollup-overdue-total">{total(each.map((o) => o.total))}</strong>
    </p>
  );
}
import { createFileRoute } from '@tanstack/react-router';
import { HomeMain } from '../slots/defs/homeMain';
import { forSlot } from '../slots/registry';

// The home page. A page is a file under routes/ — `createFileRoute('<its url>')` — with its nav
// link under features/. Its body is the home.main region, filled by features.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  if (forSlot(HomeMain.id).length === 0) {
    return <p data-testid="home-empty">Nothing here yet.</p>;
  }
  return <HomeMain.Slot />;
}
import { Outlet, createRootRouteWithContext } from '@tanstack/react-router';
import type { QueryClient } from '@tanstack/react-query';
import { AppHeader } from '../slots/defs/appHeader';
import { AppNav } from '../slots/defs/appNav';

// The shell. It renders the header region (filled from app.header), the nav region (filled from app.nav) and the matched route's component
// (from routes/); it reads no page list and holds no view state — URL search params carry what is
// open or filtered.
export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  // Search params are an open namespace, declared once here and inherited by every route: a key is
  // used by reading/writing it (url/useSearchParam), with no per-key schema.
  validateSearch: (search: Record<string, unknown>) => search,
  component: AppShell,
});

function AppShell() {
  return (
    <div data-testid="app-root">
      <header data-testid="app-header">
        <AppHeader.Slot />
      </header>
      <nav data-testid="app-nav">
        <AppNav.Slot />
      </nav>
      <main data-testid="app-home">
        <Outlet />
      </main>
    </div>
  );
}

