import { AppHeader } from '../../slots/defs/appHeader';
import { SheetPicker } from './SheetPicker';
import { SheetToday } from './SheetToday';
import { SignIn } from './SignIn';

export const contributions = [
  AppHeader.fill({ order: 0, Component: SignIn }),
  AppHeader.fill({ order: 10, Component: SheetPicker }),
  AppHeader.fill({ order: 20, Component: SheetToday }),
];
import { defineSlot } from '../Slot';

/** The shell's header bar, above the nav: who is signed in and which sheet is active. */
export const AppHeader = defineSlot('app.header');
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules } from '../settings/settings';
import { personDue, total, useRates } from './rates';

// The sheet's due-total: everyone's due-total added up, skipping those that are n/a.
export function DueTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();

  if (!user || !sheet) return null;

  const dues = people.map((p) => personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, p.holds, rules));
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{total(dues)}</strong>
    </p>
  );
}
import { HomeMain } from '../../slots/defs/homeMain';
import { Summary } from './Summary';

export const contribution = HomeMain.fill({ order: 50, Component: Summary });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
